public int missingNumber(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == nums.length) {
                continue;
            }
            while (nums[i] != i) {
                int temp = nums[nums[i]];
                nums[nums[i]] = nums[i];
                nums[i] = temp;
                if (nums[i] == nums.length) {
                    break;
                }
            }
        }
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != i) {
                return i;
            }
        }
        return nums.length;
    }

public int missingNumber(int[] nums) {
        long ans = nums.length;
        for (int i = 0; i < nums.length; i++) {
            ans = ans + i - nums[i];
        }
        return Math.toIntExact(ans);
    }
